import {
  createRootRoute,
  createRoute,
  createRouter,
  Outlet,
  RouterProvider,
  useLoaderData,
  createMemoryHistory,
} from '@tanstack/react-router';

export const rootRoute = createRootRoute({ component: () => <Outlet /> });

export async function fetchTodo(id: number): Promise<{ id: number; title: string }> {
  const r = await fetch('/api/todos/' + id);
  return r.json();
}

export function TodoView() {
  const todo = useLoaderData({ from: todoRoute.id });
  return <p>{todo.title}</p>;
}

export const todoRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: '/todos/$id',
  parseParams: (p: { id: string }) => ({ id: Number(p.id) }),
  loader: ({ params }) => fetchTodo(params.id),
  component: TodoView,
});

const routeTree = rootRoute.addChildren([todoRoute]);

export function makeRouter(initialEntries: string[] = ['/todos/1']) {
  return createRouter({
    routeTree,
    history: createMemoryHistory({ initialEntries }),
  });
}

export function App({ initialEntries }: { initialEntries?: string[] }) {
  return <RouterProvider router={makeRouter(initialEntries)} />;
}
